contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.AdjustBetAmounts(amount + 1); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        uint256 limitBefore = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 diffBefore = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 before = address(c).balance;
        bool reverted;
        c.donate{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted ||
            (address(c).balance == before &&
             c.ethBalance() == before &&
             c.currentBetLimit() == limitBefore &&
             c.currentDifficulty() == diffBefore)
        );
    }
    receive() external payable {}
}

