pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.AdjustBetAmounts(amount + 1) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        uint256 limitBefore;
        try c.currentBetLimit() returns (uint256 __r) { limitBefore = __r; } catch { return; }
        uint256 diffBefore;
        try c.currentDifficulty() returns (uint256 __r) { diffBefore = __r; } catch { return; }
        uint256 before = address(c).balance;
        bool reverted;
        try c.donate{value: amount}() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted ||
            (address(c).balance == before &&
             c.ethBalance() == before &&
             c.currentBetLimit() == limitBefore &&
             c.currentDifficulty() == diffBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
